class TicTacToe
{
    vector<int> rows, cols;
    int diagonal = 0, antiDiagonal = 0, n;
public:
    TicTacToe(int n) : rows(n, 0), cols(n, 0), n(n) {}
    int move(int row, int col, int player)
    {
        int delta = player == 1 ? 1 : -1;
        rows[row] += delta;
        cols[col] += delta;
        if (row == col) diagonal += delta;
        if (row + col == n - 1) antiDiagonal += delta;
        if (abs(rows[row]) == n || abs(cols[col]) == n ||
            abs(diagonal) == n || abs(antiDiagonal) == n)
            {
            return player;
        }
        return 0;
    }
};
